import { Object3D, Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{ imageUrl: string }} assets
 * @property {[number, number, number]} position
 * @property {[number, number, number]} rotation
 * @property {[number, number, number]} scale
 *
 * @typedef {Object} NodeContext
 * @property {(url: string) => import('three').Texture} textureLoader
 * @property {{ [key: string]: Function }} primitives
 */

/**
 * Creates a textured plane node for the Features card.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Geometry respects the source rectangle aspect (512 × 320 → 1.6 : 1)
  const geometry = new PlaneGeometry(1.6, 1);

  // Load texture (cached by ctx.textureLoader)
  const texture = ctx.textureLoader(config.assets.imageUrl);

  // Basic unlit material with the loaded texture
  const material = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
    alphaTest: 0.01,
  });

  // Create mesh and apply placement transforms
  const mesh = new Mesh(geometry, material);
  if (Array.isArray(config.position)) mesh.position.set(...config.position);
  if (Array.isArray(config.rotation)) mesh.rotation.set(...config.rotation);
  if (Array.isArray(config.scale)) mesh.scale.set(...config.scale);

  // Container object (allows future extensibility)
  const root = new Object3D();
  root.add(mesh);

  // Event handler placeholder (no interactions defined)
  root.userData.handlers = {};

  // Cleanup disposes of owned resources; texture is reference‑counted by the loader
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // If a timeline were created it would be killed here:
    // gsap.globalTimeline.kill(); // placeholder – none used in this node
  };

  return root;
}
